      rdn ASEGS M (Z_to_bv 64 A1) (length fdata) = Some fdata ->
      dinvA [(A1, CAP)] LK0 crC A M model -> incl A0 A ->
      m_fds model = fds0 -> m_fs model = fs0 ->
      srealizes ASEGS scfg (mkCfg (mkst R (Z_to_bv 64 0x153a7c) M (seg_rom ASEGS)) model) KC.

